1	/**
2	 * The reducer behind `useOptimisticIssues`.
3	 *
4	 * It is deliberately a pure function of `(issues, action)` so that the board
5	 * and the list produce identical intermediate states, and so the transition
6	 * rules (a closed issue gets a `completedAt`, reopening clears it) can be
7	 * tested without React. The server action is still the authority — this only
8	 * decides what the user sees between the click and the revalidation.
9	 */
10	import { toIsoTimestamp } from "@/types/common";
11	import type { IssueId, IsoTimestamp, UserId } from "@/types/common";
12	import { CLOSED_ISSUE_STATUSES, type Issue, type IssueStatus } from "@/types/issue";
13	
14	export type OptimisticIssueAction =
15	  | { readonly kind: "status"; readonly issueId: IssueId; readonly status: IssueStatus }
16	  | {
17	      readonly kind: "assignee";
18	      readonly issueId: IssueId;
19	      readonly assigneeId: UserId | null;
20	    };
21	
22	export function isClosedStatus(status: IssueStatus): boolean {
23	  return CLOSED_ISSUE_STATUSES.includes(status);
24	}
25	
26	/** Applies one status change, keeping the lifecycle timestamps coherent. */
27	export function withStatus(
28	  issue: Issue,
29	  status: IssueStatus,
30	  at: IsoTimestamp,
31	): Issue {
32	  if (issue.status === status) return issue;
33	  const closing = isClosedStatus(status);
34	  return {
35	    ...issue,
36	    status,
37	    updatedAt: at,
38	    startedAt:
39	      issue.startedAt === null && status === "in_progress" ? at : issue.startedAt,
40	    completedAt: closing ? (issue.completedAt ?? at) : null,
41	  };
42	}
43	
44	export function withAssignee(
45	  issue: Issue,
46	  assigneeId: UserId | null,
47	  at: IsoTimestamp,
48	): Issue {
49	  if (issue.assigneeId === assigneeId) return issue;
50	  return { ...issue, assigneeId, updatedAt: at };
51	}
52	
53	export function optimisticIssuesReducer(
54	  issues: readonly Issue[],
55	  action: OptimisticIssueAction,
56	): readonly Issue[] {
57	  const at = toIsoTimestamp(new Date());
58	  return issues.map((issue) => {
59	    if (issue.id !== action.issueId) return issue;
60	    return action.kind === "status"
61	      ? withStatus(issue, action.status, at)
62	      : withAssignee(issue, action.assigneeId, at);
63	  });
64	}
